// PROTOTYPE helper. Pulls the shipped recipe set out of a built japanese-batch-kitchen page
// (the JSON literal after `const DATA = `) and writes it next to the prototype as data.js.
// Nothing from the source folder is executed; the JSON is parsed as data.
//
//   node prototype/device-ui/make-data.js "C:\path\to\japanese-batch-kitchen\dist\batch-kitchen.html"
const fs = require('fs');
const path = require('path');

const src = process.argv[2];
if (!src) { console.error('usage: node make-data.js <path to batch-kitchen.html>'); process.exit(1); }
const html = fs.readFileSync(src, 'utf8');
const a = html.indexOf('const DATA = ');
const b = html.indexOf(';\nconst { R, ING, UT } = DATA;');
if (a < 0 || b < 0) throw new Error('DATA literal not found; is this a built batch-kitchen.html?');
const data = JSON.parse(html.slice(a + 'const DATA = '.length, b));

const out = path.join(__dirname, 'data.js');
fs.writeFileSync(out, '// Generated by make-data.js from japanese-batch-kitchen. Recipes are Shota Horii\'s (TikTok @aisletotokyo).\nwindow.EVEY_DATA = ' + JSON.stringify(data) + ';\n');
console.log(`wrote ${out}: ${data.R.length} recipes, ${Object.keys(data.ING).length} ingredients, ${Object.keys(data.UT).length} utensils`);
